def encode(input):
    """Percent-encode non-alphanumeric bytes; alphanumeric pass through unchanged."""
    out = bytearray()
    for b in input:
        if b in alphanumeric:
            out.append(b)
        else:
            out += b'%%%02X' % b
    return bytes(out)


hexdigits = b'0123456789abcdefABCDEF'


def decode(buf):
    """Decode a percent-encoded byte string back to the original bytes.

    Partial percent sequences at either end (caused by truncation) are dropped.
    """
    out = bytearray()
    i = 0
    while i < len(buf):
        if buf[i] == ord('%'):
            if i + 2 >= len(buf):
                break  # truncated escape tail: drop it
            if buf[i + 1] in hexdigits and buf[i + 2] in hexdigits:
                out.append(int(buf[i + 1:i + 3], 16))
                i += 3
            else:
                i += 1  # not a valid escape: drop the '%'
        else:
            out.append(buf[i])
            i += 1
    return bytes(out)
